/* eslint-disable no-restricted-syntax, no-invalid-this, stdlib/no-empty-lines-between-requires */

'use strict';

// MODULES //

var EventEmitter = require( 'events' ).EventEmitter;
var logger = require( 'debug' );
var isObject = require( '@stdlib/assert/is-object' );
var setNonEnumerableReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var setNonEnumerableReadOnlyAccessor = require( '@stdlib/utils/define-nonenumerable-read-only-accessor' ); // eslint-disable-line id-length
var setReadWriteAccessor = require( '@stdlib/utils/define-read-write-accessor' );
var hasProp = require( '@stdlib/assert/has-property' );
var inherit = require( '@stdlib/utils/inherit' );
var objectKeys = require( '@stdlib/utils/keys' );
var instance2json = require( '@stdlib/plot/vega/base/to-json' );
var transformErrorMessage = require( '@stdlib/plot/vega/base/transform-validation-message' );
var format = require( '@stdlib/string/format' );
var properties = require( './properties.json' );
var defaults = require( './defaults.js' );

// Note: keep the following in alphabetical order according to the `require` path...
var getAs = require( './as/get.js' );
var setAs = require( './as/set.js' );

var getEndAngle = require( './end-angle/get.js' );
var setEndAngle = require( './end-angle/set.js' );

var getField = require( './field/get.js' );
var setField = require( './field/set.js' );

var getProperties = require( './properties/get.js' );

var getSort = require( './sort/get.js' );
var setSort = require( './sort/set.js' );

var getStartAngle = require( './start-angle/get.js' );
var setStartAngle = require( './start-angle/set.js' );


// VARIABLES //

var debug = logger( 'vega:pie-transform:main' );


// MAIN //

/**
* Pie transform constructor.
*
* @constructor
* @param {Options} options - constructor options
* @param {ArrayLikeObject<string>} [options.as=['startAngle','endAngle']] - output field names for the computed start and end angle values
* @param {NonNegativeNumber} [options.endAngle=2*PI] - end angle of the pie in radians
* @param {Field} [options.field] - data field determining pie slice size (if not provided, all pie slices have an equal size)
* @param {boolean} [options.sort=false] - boolean indicating whether to sort arcs according to field values
* @param {NonNegativeNumber} [options.startAngle=0] - starting angle of the pie in radians
* @throws {TypeError} options argument must be an object
* @throws {Error} must provide valid options
* @returns {PieTransform} pie transform instance
*
* @example
* var Field = require( '@stdlib/plot/vega/field/ctor' );
*
* var field = new Field({
*     'field': 'amount'
* });
* // returns <Field>
*
* var transform = new PieTransform({
*     'field': field
* });
* // returns <PieTransform>
*/
function PieTransform( options ) {
	var self;
	var opts;
	var keys;
	var v;
	var k;
	var i;
	if ( !( this instanceof PieTransform ) ) {
		return new PieTransform( options );
	}
	self = this;
	EventEmitter.call( this );

	if ( !isObject( options ) ) {
		throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
	}

	// Resolve the default configuration:
	opts = defaults();

	// Set internal properties according to the default configuration...
	keys = objectKeys( opts );
	for ( i = 0; i < keys.length; i++ ) {
		k = keys[ i ];
		this[ '_'+k ] = opts[ k ];
	}

	// Define an internal change event listener:
	this._onChange = onChange;

	// Add change listeners to default event emitters:
	if ( this._field && typeof this._field.on === 'function' ) {
		this._addChangeListener( this._field );
	}

	// Validate provided options by attempting to assign option values to corresponding fields...
	for ( i = 0; i < properties.length; i++ ) {
		k = properties[ i ];
		if ( !hasProp( options, k ) ) {
			continue;
		}
		v = options[ k ];
		try {
			this[ k ] = v;
		} catch ( err ) {
			debug( 'Encountered an error. Error: %s', err.message );

			// FIXME: retain thrown error type
			throw new Error( transformErrorMessage( err.message ) );
		}
	}
	return this;

	/**
	* Callback invoked upon a change event.
	*
	* @private
	* @param {Object} event - event object
	*/
	function onChange( event ) {
		debug( 'Received a change event: %s', JSON.stringify( event ) );
		self.emit( 'change', event );
	}
}

/*
* Inherit from the `EventEmitter` prototype.
*/
inherit( PieTransform, EventEmitter );

/**
* Constructor name.
*
* @private
* @name name
* @memberof PieTransform
* @readonly
* @type {string}
*/
setNonEnumerableReadOnly( PieTransform, 'name', 'PieTransform' );

/**
* Adds an internal listener to a change event on a child instance.
*
* @private
* @name _addChangeListener
* @memberof PieTransform.prototype
* @type {Function}
* @param {Object} emitter - event emitter
* @returns {PieTransform} pie transform instance
*/
setNonEnumerableReadOnly( PieTransform.prototype, '_addChangeListener', function addChangeListener( emitter ) {
	if ( emitter && typeof emitter.on === 'function' ) {
		emitter.on( 'change', this._onChange );
	}
	return this;
});

/**
* Adds internal listeners to change events on child instances.
*
* @private
* @name _addChangeListeners
* @memberof PieTransform.prototype
* @type {Function}
* @param {ArrayLikeObject<Object>} emitters - list of event emitters
* @returns {PieTransform} pie transform instance
*/
setNonEnumerableReadOnly( PieTransform.prototype, '_addChangeListeners', function addChangeListeners( emitters ) {
	var i;
	for ( i = 0; i < emitters.length; i++ ) {
		this._addChangeListener( emitters[ i ] );
	}
	return this;
});

/**
* Removes an internal listener to a change event on a child instance.
*
* @private
* @name _removeChangeListener
* @memberof PieTransform.prototype
* @type {Function}
* @param {Object} emitter - event emitter
* @returns {PieTransform} pie transform instance
*/
setNonEnumerableReadOnly( PieTransform.prototype, '_removeChangeListener', function removeChangeListener( emitter ) {
	if ( emitter && typeof emitter.removeListener === 'function' ) {
		emitter.removeListener( 'change', this._onChange );
	}
	return this;
});

/**
* Removes internal listeners to change events on child instances.
*
* @private
* @name _removeChangeListeners
* @memberof PieTransform.prototype
* @type {Function}
* @param {ArrayLikeObject<Object>} emitters - list of event emitters
* @returns {PieTransform} pie transform instance
*/
setNonEnumerableReadOnly( PieTransform.prototype, '_removeChangeListeners', function removeChangeListeners( emitters ) {
	var i;
	for ( i = 0; i < emitters.length; i++ ) {
		this._removeChangeListener( emitters[ i ] );
	}
	return this;
});

/**
* Output field names for the computed start and end angle values.
*
* @name as
* @memberof PieTransform.prototype
* @type {ArrayLikeObject<string>}
* @default ['startAngle','endAngle']
*
* @example
* var transform = new PieTransform({
*     'as': [ 'foo', 'bar' ]
* });
*
* var v = transform.as;
* // returns [ 'foo', 'bar' ]
*/
setReadWriteAccessor( PieTransform.prototype, 'as', getAs, setAs );

/**
* End angle of the pie in radians.
*
* @name endAngle
* @memberof PieTransform.prototype
* @type {NonNegativeNumber}
* @default 2*PI
*
* @example
* var transform = new PieTransform({
*     'endAngle': 3.141592653589793
* });
*
* var v = transform.endAngle;
* // returns 3.141592653589793
*/
setReadWriteAccessor( PieTransform.prototype, 'endAngle', getEndAngle, setEndAngle );

/**
* Data field determining pie slice size.
*
* ## Notes
*
* -   If not set, all pie slices have an equal size.
*
* @name field
* @memberof PieTransform.prototype
* @type {(Field|void)}
*
* @example
* var Field = require( '@stdlib/plot/vega/field/ctor' );
*
* var field = new Field({
*     'field': 'amount'
* });
*
* var transform = new PieTransform({
*     'field': field
* });
*
* var v = transform.field;
* // returns <Field>
*/
setReadWriteAccessor( PieTransform.prototype, 'field', getField, setField );

/**
* Pie transform properties.
*
* @name properties
* @memberof PieTransform.prototype
* @type {Array<string>}
*
* @example
* var transform = new PieTransform({});
*
* var v = transform.properties;
* // returns [...]
*/
setNonEnumerableReadOnlyAccessor( PieTransform.prototype, 'properties', getProperties );

/**
* Boolean indicating whether to sort arcs according to field values.
*
* @name sort
* @memberof PieTransform.prototype
* @type {boolean}
* @default false
*
* @example
* var transform = new PieTransform({
*     'sort': true
* });
*
* var v = transform.sort;
* // returns true
*/
setReadWriteAccessor( PieTransform.prototype, 'sort', getSort, setSort );

/**
* Starting angle of the pie in radians.
*
* @name startAngle
* @memberof PieTransform.prototype
* @type {NonNegativeNumber}
* @default 0
*
* @example
* var transform = new PieTransform({
*     'startAngle': 1.5707963267948966
* });
*
* var v = transform.startAngle;
* // returns 1.5707963267948966
*/
setReadWriteAccessor( PieTransform.prototype, 'startAngle', getStartAngle, setStartAngle );

/**
* Serializes an instance to a JSON object.
*
* ## Notes
*
* -   This method is implicitly invoked by `JSON.stringify`.
*
* @name toJSON
* @memberof PieTransform.prototype
* @type {Function}
* @returns {Object} JSON object
*
* @example
* var transform = new PieTransform({});
*
* var v = transform.toJSON();
* // returns {...}
*/
setNonEnumerableReadOnly( PieTransform.prototype, 'toJSON', function toJSON() {
	return instance2json( this, properties );
});


// EXPORTS //

module.exports = PieTransform;
